    private func roundTrip(_ name:String,_ value:Any) throws -> Data {
        let data=try JSONSerialization.data(withJSONObject:value)
        let decoder=CodableHelper.jsonDecoder,encoder=CodableHelper.jsonEncoder
        switch name {
        case "WorkoutControlActionRequest": return try encoder.encode(decoder.decode(WorkoutControlActionRequest.self,from:data))
        case "WorkoutControlView": return try encoder.encode(decoder.decode(WorkoutControlView.self,from:data))
        case "WorkoutControlReceipt": return try encoder.encode(decoder.decode(WorkoutControlReceipt.self,from:data))
        case "WorkoutControlOccurrence": return try encoder.encode(decoder.decode(WorkoutControlOccurrence.self,from:data))
        case "WorkoutControlValues": return try encoder.encode(decoder.decode(WorkoutControlValues.self,from:data))
        case "WorkoutControlTimer": return try encoder.encode(decoder.decode(WorkoutControlTimer.self,from:data))
        case "WorkoutControlProblemDetails": return try encoder.encode(decoder.decode(WorkoutControlProblemDetails.self,from:data))
        case "WorkoutControlPausePayload": return try encoder.encode(decoder.decode(WorkoutControlPausePayload.self,from:data))
        case "WorkoutControlEntryValues": return try encoder.encode(decoder.decode(WorkoutControlEntryValues.self,from:data))
        default: throw NSError(domain:"unknown fixture",code:1)
        }
    }
    func testActualTypedCodecPositiveAndNegativeShapes() throws {
        let all=try JSONSerialization.jsonObject(with:Data(fixtures.utf8)) as! [String:[[String:Any]]]
        for f in all["positives"]! {
            let data=try roundTrip(f["name"] as! String,f["value"]!)
            let encoded=try JSONSerialization.jsonObject(with:data) as! NSDictionary
            func normalized(_ value: Any) -> Any {
                if let s=value as? String { return s.replacingOccurrences(of:".000Z",with:"Z") }
                if let m=value as? [String: Any] {
                    var fields=m.mapValues(normalized)
                    if let actions=m["allowedActions"] as? [String] { fields["allowedActions"]=actions.sorted() }
                    return fields
                }
                if let a=value as? [Any] { return a.map(normalized) }
                return value
            }
            let original=normalized(f["value"]!) as! NSDictionary
            XCTAssertEqual(normalized(encoded) as! NSDictionary,original,"positive \(f["label"]!)")
        }
        for f in all["negatives"]! {
            XCTAssertThrowsError(try roundTrip(f["name"] as! String,f["value"]!),"negative \(f["label"]!)")
        }
    }
    func testRequestBuilderPreservesCanonicalIdentityOpaqueETagAndRetryBody() throws {
        let all=try JSONSerialization.jsonObject(with:Data(fixtures.utf8)) as! [String:[[String:Any]]]
        let raw=all["positives"]![0]["value"] as! [String:Any]
        let data=try JSONSerialization.data(withJSONObject:raw)
        let request=try CodableHelper.jsonDecoder.decode(WorkoutControlActionRequest.self,from:data)
        let key=UUID(uuidString:raw["operationId"] as! String)!
        let tag="\"Ctl_MiXeD-4\""
        let first=WorkoutExecutionAPI.executeStudentWorkoutControlActionWithRequestBuilder(sessionId:"session",idempotencyKey:key,ifMatch:tag,workoutControlActionRequest:request)
        let second=WorkoutExecutionAPI.executeStudentWorkoutControlActionWithRequestBuilder(sessionId:"session",idempotencyKey:key,ifMatch:tag,workoutControlActionRequest:request)
        XCTAssertEqual(first.headers["Idempotency-Key"],raw["operationId"] as? String)
        XCTAssertEqual(first.headers["If-Match"],tag)
        XCTAssertEqual(first.headers,second.headers)
        let body=try XCTUnwrap(first.parameters?["jsonData"] as? Data)
        let retried=try XCTUnwrap(second.parameters?["jsonData"] as? Data)
        XCTAssertEqual(body,retried)
        let decoded=try JSONSerialization.jsonObject(with:body) as! [String:Any]
        XCTAssertEqual(decoded["operationId"] as? String,raw["operationId"] as? String)
        XCTAssertEqual(decoded["expiresAt"] as? String,raw["expiresAt"] as? String)
    }
    func testMicroNanoLiteralDeadlinesSurviveRequestBuilderRetries() throws {
        let all=try JSONSerialization.jsonObject(with:Data(fixtures.utf8)) as! [String:[[String:Any]]]
        for f in all["positives"]! where (f["label"] as? String)?.hasPrefix("literal-expiry-") == true {
            let raw=f["value"] as! [String:Any]
            let data=try JSONSerialization.data(withJSONObject:raw)
            let action=try CodableHelper.jsonDecoder.decode(WorkoutControlActionRequest.self,from:data)
            let key=UUID(uuidString:raw["operationId"] as! String)!
            let first=WorkoutExecutionAPI.executeStudentWorkoutControlActionWithRequestBuilder(sessionId:"s",idempotencyKey:key,ifMatch:"opaque",workoutControlActionRequest:action)
            let second=WorkoutExecutionAPI.executeStudentWorkoutControlActionWithRequestBuilder(sessionId:"s",idempotencyKey:key,ifMatch:"opaque",workoutControlActionRequest:action)
            let body=try XCTUnwrap(first.parameters?["jsonData"] as? Data)
            XCTAssertEqual(body,second.parameters?["jsonData"] as? Data)
            let value=try JSONSerialization.jsonObject(with:body) as! [String:Any]
            XCTAssertEqual(value["expiresAt"] as? String,raw["expiresAt"] as? String)
        }
    }
    private func nativeEntry(_ literal:String)->Data {
        Data(#"{"loadValue":WWC_NUMBER,"loadUnit":"KG","reps":0}"#.replacingOccurrences(of:"WWC_NUMBER",with:literal).utf8)
    }
    private func nativeAction(_ literal:String)->Data {
        let entry=String(data:nativeEntry(literal),encoding:.utf8)!
        return Data(#"{"operationId":"019a4e10-7c21-7b3a-9c6d-4f0a2b8e1d11","action":"APPLY_VALUES","expiresAt":"2026-11-04T10:00:30.123456Z","phaseId":"phase-current-opaque","occurrence":{"occurrenceId":"occurrence-current-opaque","prescribedExerciseId":"prescribed-exercise-opaque","prescribedSetId":"prescribed-set-opaque"},"payload":{"values":WWC_ENTRY}}"#.replacingOccurrences(of:"WWC_ENTRY",with:entry).utf8)
    }
    private func nativeBuilder(_ data:Data) throws -> RequestBuilder<WorkoutControlReceipt> {
        let action=try CodableHelper.jsonDecoder.decode(WorkoutControlActionRequest.self,from:data)
        return WorkoutExecutionAPI.executeStudentWorkoutControlActionWithRequestBuilder(sessionId:"s",idempotencyKey:UUID(uuidString:"019a4e10-7c21-7b3a-9c6d-4f0a2b8e1d11")!,ifMatch:#""Ctl_mixed-4""#,workoutControlActionRequest:action)
    }
    private func assertSameNativeNumber(_ data:Data,_ original:String,file:StaticString = #filePath,line:UInt = #line) throws {
        let text=try XCTUnwrap(String(data:data,encoding:.utf8),file:file,line:line)
        let parts=text.components(separatedBy:#""loadValue""#)
        XCTAssertEqual(parts.count,2,file:file,line:line)
        guard parts.count == 2,let colon=parts[1].firstIndex(of:":") else {return}
        let rest=parts[1][parts[1].index(after:colon)...].trimmingCharacters(in:.whitespacesAndNewlines)
        let token=String(rest.prefix { !",} \n\r\t".contains($0) })
        let before=try XCTUnwrap(WorkoutControlJSONNumber(original),file:file,line:line)
        let after=try XCTUnwrap(WorkoutControlJSONNumber(token),file:file,line:line)
        XCTAssertEqual(before.compare(after),0,file:file,line:line)
    }
    func testSchemaValidUnrepresentableNumbersFailExplicitlyBeforeModelOrBuilder() throws {
        for literal in ["12345678901234567890.1234567890123456789","9007199254740993","0.10000000000000000000000001","1e400","1e-400"] {
            let number=try XCTUnwrap(WorkoutControlJSONNumber(literal))
            XCTAssertTrue(WorkoutControlWireGuard.accepts("WorkoutControlEntryValues",["loadValue":number,"loadUnit":"KG","reps":0]))
            func nativeFailure(_ error:Error) {
                guard case DecodingError.dataCorrupted(let context)=error else {return XCTFail("Expected explicit native representability failure")}
                XCTAssertTrue(context.debugDescription.contains("not losslessly representable"))
            }
            XCTAssertThrowsError(try CodableHelper.jsonDecoder.decode(WorkoutControlEntryValues.self,from:nativeEntry(literal)),"EntryValues precision limit",nativeFailure)
            XCTAssertThrowsError(try CodableHelper.jsonDecoder.decode(WorkoutControlActionRequest.self,from:nativeAction(literal)),"Action precision limit",nativeFailure)
            XCTAssertThrowsError(try nativeBuilder(nativeAction(literal)),"Builder precision limit",nativeFailure)
        }
    }
    func testLosslessNativeNumberControlsAndEquivalentExponentsRemainValid() throws {
        for literal in ["0.5","0","22.25","225e-1","9007199254740992","1e200","1e-200"] {
            let entry=try CodableHelper.jsonDecoder.decode(WorkoutControlEntryValues.self,from:nativeEntry(literal))
            try assertSameNativeNumber(CodableHelper.jsonEncoder.encode(entry),literal)
            let action=try CodableHelper.jsonDecoder.decode(WorkoutControlActionRequest.self,from:nativeAction(literal))
            try assertSameNativeNumber(CodableHelper.jsonEncoder.encode(action),literal)
            let body=try XCTUnwrap(nativeBuilder(nativeAction(literal)).parameters?["jsonData"] as? Data)
            try assertSameNativeNumber(body,literal)
            let wire=try JSONSerialization.jsonObject(with:body) as! [String:Any]
            XCTAssertEqual(wire["expiresAt"] as? String,"2026-11-04T10:00:30.123456Z")
        }
        struct OutsideWWC:Codable {let loadValue:Double}
        XCTAssertNoThrow(try CodableHelper.jsonDecoder.decode(OutsideWWC.self,from:nativeEntry("12345678901234567890.1234567890123456789")))
    }
    func testUnrepresentableWireNumbersFailExplicitlyWithoutZeroOrNaN() {
        for literal in ["1e400","1e-400"] {
            let json="{\"loadValue\":\(literal),\"loadUnit\":\"KG\",\"reps\":0}"
            XCTAssertThrowsError(try CodableHelper.jsonDecoder.decode(WorkoutControlEntryValues.self,from:Data(json.utf8)))
        }
    }
    func testExactRawNumericTokensUseSDKBoundaryBeforeFoundation() throws {
        XCTAssertTrue(CodableHelper.jsonDecoder is WorkoutControlJSONDecoder)
        XCTAssertThrowsError(try roundTripRaw("WorkoutControlTimer",#"{"timerId":"t","phaseId":"p","kind":"SET","serverAnchor":"2026-11-04T10:00:00Z","activeElapsedMilliseconds":9007199254740990.5,"paused":false}"#))
        XCTAssertThrowsError(try roundTripRaw("WorkoutControlTimer",#"{"timerId":"t","phaseId":"p","kind":"SET","serverAnchor":"2026-11-04T10:00:00Z","activeElapsedMilliseconds":9007199254740991.00000000000000001,"paused":false}"#))
        XCTAssertThrowsError(try roundTripRaw("WorkoutControlTimer",#"{"timerId":"t","phaseId":"p","kind":"SET","serverAnchor":"2026-11-04T10:00:00Z","activeElapsedMilliseconds":9007199254740991.00000000000000000000000000000000001,"paused":false}"#))
        XCTAssertThrowsError(try roundTripRaw("WorkoutControlEntryValues",#"{"loadValue":-1e-400,"loadUnit":"KG","reps":0}"#))
        struct OutsideWWC:Decodable { let value:Int64 }
        // The boundary does not introduce assertions into unrelated DTOs.
        XCTAssertNoThrow(try CodableHelper.jsonDecoder.decode(OutsideWWC.self,from:Data(#"{"value":9007199254740990.5}"#.utf8)))
    }
    private func roundTripRaw(_ name:String,_ json:String) throws -> Data {
        let decoder=CodableHelper.jsonDecoder,encoder=CodableHelper.jsonEncoder,data=Data(json.utf8)
        switch name {
        case "WorkoutControlTimer": return try encoder.encode(decoder.decode(WorkoutControlTimer.self,from:data))
        default: return try encoder.encode(decoder.decode(WorkoutControlEntryValues.self,from:data))
        }
    }
    func testActualTypedEncodeRejectsInvalidLoadPair() {
        let value=WorkoutControlEntryValues(loadValue:10,loadUnit:nil,reps:0)
        XCTAssertThrowsError(try CodableHelper.jsonEncoder.encode(value))
        let unknown=WorkoutControlEntryValues(loadValue:10,loadUnit:.unknownDefaultOpenApi,reps:0)
        XCTAssertThrowsError(try CodableHelper.jsonEncoder.encode(unknown))
    }
